window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-752e837edd5d18ef"]={"versions": [{"id": "FIG-752e837edd5d18ef", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts des E2E-Profils 7 (<code>E2E Profile 7 Protect step \"Write Counter\"</code>). Das Diagramm operationalisiert einen Teilschritt der Funktion <code>E2E_P07Protect()</code> innerhalb der AUTOSAR E2E-Bibliothek (Classic & Adaptive Platform), zuständig für den standardisierten End-to-End-Datenschutz über unzuverlässige Kommunikationsmedien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext</strong>: <code>E2E_P07Protect()</code> (gekennzeichnet über ein aufrufendes Aktivitäts-/Subprozess-Symbol oben links).</li>\n<li><strong>Zustandsstruktur / Variablen</strong>: <code>State-&gt;Counter</code> (4 Byte breiter Zählerwert aus dem E2E-Zustandsobjekt).</li>\n<li><strong>Datenpuffer</strong>: <code>Data[]</code> (zu schützendes Byte-Array).</li>\n<li><strong>Konfigurationsparameter / Offsets</strong>: <code>Offset</code> (Basisverschiebung innerhalb des Nutzdatenpuffers), spezifisch die Ziel-Byte-Positionen <code>Data[Offset+12...Offset+15]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Startknoten</strong>: Eintritt in den Einzelschritt \"Write Counter\".</li>\n<li><strong>Aktionszustand</strong>: Ausführung der Operation <code>Copy 4-byte State-&gt;Counter on bytes Data[Offset+12...Offset+15] in Big Endian order</code>. Der 32-Bit-Wert von <code>State-&gt;Counter</code> wird serialisiert in Big-Endian-Bytereihenfolge auf die relativen Bytepositionen 12 bis 15 bezogen auf <code>Offset</code> in das Datenarray <code>Data</code> geschrieben.</li>\n<li><strong>Endknoten</strong>: Verlassen der Aktivität nach erfolgreichem Schreiben des Zählers.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00490]</code> für Implementierungen von E2E Profile 7. Der Zähler belegt exakt 4 Bytes an Offset + 12 bis Offset + 15 in Netzwerk-Bytereihenfolge (Most Significant Byte zuerst). Implementierer müssen sicherstellen, dass das zugrundeliegende Puffer-Array <code>Data</code> an der Position <code>Offset + 15</code> gültig und beschreibbar ist.</p>"}, {"id": "FIG-061d92355a3aff71", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Einzelschritts des E2E-Profils 7 (<code>E2E Profile 7 Protect step \"Write Counter\"</code>). Das Diagramm operationalisiert einen Teilschritt der Funktion <code>E2E_P07Protect()</code> innerhalb der AUTOSAR E2E-Bibliothek (Classic & Adaptive Platform), zuständig für den standardisierten End-to-End-Datenschutz über unzuverlässige Kommunikationsmedien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionskontext</strong>: <code>E2E_P07Protect()</code> (gekennzeichnet über ein aufrufendes Aktivitäts-/Subprozess-Symbol oben links).</li>\n<li><strong>Zustandsstruktur / Variablen</strong>: <code>State-&gt;Counter</code> (4 Byte breiter Zählerwert aus dem E2E-Zustandsobjekt).</li>\n<li><strong>Datenpuffer</strong>: <code>Data[]</code> (zu schützendes Byte-Array).</li>\n<li><strong>Konfigurationsparameter / Offsets</strong>: <code>Offset</code> (Basisverschiebung innerhalb des Nutzdatenpuffers), spezifisch die Ziel-Byte-Positionen <code>Data[Offset+12...Offset+15]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Startknoten</strong>: Eintritt in den Einzelschritt \"Write Counter\".</li>\n<li><strong>Aktionszustand</strong>: Ausführung der Operation <code>Copy 4-byte State-&gt;Counter on bytes Data[Offset+12...Offset+15] in Big Endian order</code>. Der 32-Bit-Wert von <code>State-&gt;Counter</code> wird serialisiert in Big-Endian-Bytereihenfolge auf die relativen Bytepositionen 12 bis 15 bezogen auf <code>Offset</code> in das Datenarray <code>Data</code> geschrieben.</li>\n<li><strong>Endknoten</strong>: Verlassen der Aktivität nach erfolgreichem Schreiben des Zählers.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00490]</code> für Implementierungen von E2E Profile 7. Der Zähler belegt exakt 4 Bytes an Offset + 12 bis Offset + 15 in Netzwerk-Bytereihenfolge (Most Significant Byte zuerst). Implementierer müssen sicherstellen, dass das zugrundeliegende Puffer-Array <code>Data</code> an der Position <code>Offset + 15</code> gültig und beschreibbar ist.</p>"}], "trans": [{"from": "FIG-752e837edd5d18ef", "to": "FIG-061d92355a3aff71", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
